inline bool operator==(const VariableValueUnion &lhs, const VariableValueUnion &rhs) {
  if (lhs.type != rhs.type) return false;
  switch (lhs.type) {
    case VariableValue_NONE: {
      return true;
    }
    case VariableValue_VarInt: {
      return *(reinterpret_cast<const Tryll::VarIntT *>(lhs.value)) ==
             *(reinterpret_cast<const Tryll::VarIntT *>(rhs.value));
    }
    case VariableValue_VarFloat: {
      return *(reinterpret_cast<const Tryll::VarFloatT *>(lhs.value)) ==
             *(reinterpret_cast<const Tryll::VarFloatT *>(rhs.value));
    }
    case VariableValue_VarString: {
      return *(reinterpret_cast<const Tryll::VarStringT *>(lhs.value)) ==
             *(reinterpret_cast<const Tryll::VarStringT *>(rhs.value));
    }
    case VariableValue_VarBool: {
      return *(reinterpret_cast<const Tryll::VarBoolT *>(lhs.value)) ==
             *(reinterpret_cast<const Tryll::VarBoolT *>(rhs.value));
    }
    case VariableValue_VarStringSet: {
      return *(reinterpret_cast<const Tryll::VarStringSetT *>(lhs.value)) ==
             *(reinterpret_cast<const Tryll::VarStringSetT *>(rhs.value));
    }
    default: {
      return false;
    }
  }
}

inline bool operator!=(const VariableValueUnion &lhs, const VariableValueUnion &rhs) {
    return !(lhs == rhs);
}

