           VerifyField<uint64_t>(verifier, VT_AGENT_ID, 8) &&
           VerifyOffset(verifier, VT_FORMAT) &&
           verifier.VerifyTable(format()) &&
           VerifyOffset(verifier, VT_NODE_NAME) &&
           verifier.VerifyString(node_name()) &&
           verifier.EndTable();
