inline ::flatbuffers::Offset<MemoryComponent> CreateMemoryComponent(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> kind = 0,
    ::flatbuffers::Offset<::flatbuffers::String> name = 0,
    Tryll::MemoryOwnerKind owner = Tryll::MemoryOwnerKind_Model,
    Tryll::MemoryTier tier = Tryll::MemoryTier_Measured,
    ::flatbuffers::Offset<::flatbuffers::String> estimate_basis = 0,
    uint64_t ram_bytes = 0,
    uint64_t vram_bytes = 0,
    uint64_t ram_bytes_high = 0,
    int32_t device_index = -1,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<Tryll::MemoryComponentDevice>>> per_device = 0,
    uint64_t session_id = 0,
    uint64_t agent_id = 0,
    ::flatbuffers::Offset<::flatbuffers::String> node_name = 0,
    uint32_t used_tokens = 0,
    uint32_t capacity_tokens = 0,
    bool resident = true,
    bool occupancy_stale = false,
    uint64_t compute_bytes = 0,
    Tryll::InferenceConsumerClass consumer_class = Tryll::InferenceConsumerClass_Unspecified,
    int64_t last_turn_at_ms = 0) {
  MemoryComponentBuilder builder_(_fbb);
  builder_.add_last_turn_at_ms(last_turn_at_ms);
  builder_.add_compute_bytes(compute_bytes);
  builder_.add_agent_id(agent_id);
  builder_.add_session_id(session_id);
  builder_.add_ram_bytes_high(ram_bytes_high);
  builder_.add_vram_bytes(vram_bytes);
  builder_.add_ram_bytes(ram_bytes);
  builder_.add_capacity_tokens(capacity_tokens);
  builder_.add_used_tokens(used_tokens);
  builder_.add_node_name(node_name);
  builder_.add_per_device(per_device);
  builder_.add_device_index(device_index);
  builder_.add_estimate_basis(estimate_basis);
  builder_.add_name(name);
  builder_.add_kind(kind);
  builder_.add_consumer_class(consumer_class);
  builder_.add_occupancy_stale(occupancy_stale);
  builder_.add_resident(resident);
  builder_.add_tier(tier);
  builder_.add_owner(owner);
  return builder_.Finish();
}

