inline bool operator==(const ModelInfoT &lhs, const ModelInfoT &rhs) {
  return
      (lhs.name == rhs.name) &&
      (lhs.status == rhs.status) &&
      (lhs.huggingface_repo == rhs.huggingface_repo) &&
      (lhs.size_bytes == rhs.size_bytes) &&
      (lhs.model_type == rhs.model_type) &&
      (lhs.engine == rhs.engine) &&
      (lhs.audience == rhs.audience) &&
      (lhs.tool_call_format == rhs.tool_call_format) &&
      (lhs.context_size == rhs.context_size) &&
      (lhs.files == rhs.files) &&
      ((lhs.default_sampling == rhs.default_sampling) || (lhs.default_sampling && rhs.default_sampling && *lhs.default_sampling == *rhs.default_sampling)) &&
      (lhs.local_path == rhs.local_path) &&
      (lhs.tool_call_support == rhs.tool_call_support) &&
      (lhs.languages == rhs.languages) &&
      (lhs.dependencies.size() == rhs.dependencies.size() && std::equal(lhs.dependencies.cbegin(), lhs.dependencies.cend(), rhs.dependencies.cbegin(), [](std::unique_ptr<Tryll::ModelDependencyT> const &a, std::unique_ptr<Tryll::ModelDependencyT> const &b) { return (a == b) || (a && b && *a == *b); })) &&
      ((lhs.tts_capabilities == rhs.tts_capabilities) || (lhs.tts_capabilities && rhs.tts_capabilities && *lhs.tts_capabilities == *rhs.tts_capabilities));
}

