inline const Tryll::Message *GetMessage(const void *buf) {
  return ::flatbuffers::GetRoot<Tryll::Message>(buf);
}

inline const Tryll::Message *GetSizePrefixedMessage(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<Tryll::Message>(buf);
}

inline bool VerifyMessageBuffer(
    ::flatbuffers::Verifier &verifier) {
  return verifier.VerifyBuffer<Tryll::Message>(nullptr);
}

inline bool VerifySizePrefixedMessageBuffer(
    ::flatbuffers::Verifier &verifier) {
  return verifier.VerifySizePrefixedBuffer<Tryll::Message>(nullptr);
}

inline void FinishMessageBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<Tryll::Message> root) {
  fbb.Finish(root);
}

inline void FinishSizePrefixedMessageBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<Tryll::Message> root) {
  fbb.FinishSizePrefixed(root);
}

inline std::unique_ptr<Tryll::MessageT> UnPackMessage(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<Tryll::MessageT>(GetMessage(buf)->UnPack(res));
}

inline std::unique_ptr<Tryll::MessageT> UnPackSizePrefixedMessage(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<Tryll::MessageT>(GetSizePrefixedMessage(buf)->UnPack(res));
}

